mapper.select:



        AND member_id = #{memberId}


        AND member_no like concat('%', #{memberNo}, '%')


        AND member_name like concat('%', #{memberName}, '%')


        AND source_type = #{sourceType}


        AND create_time >= #{params.beginTime}


        AND create_time < DATE_ADD(#{params.endTime}, INTERVAL 1 DAY)


order by create_time desc
